<?php
require_once 'auth.php'; require_once 'auth_ui.php';$token=$_GET['token']??$_POST['token']??'';$error='';$success=false;$valid=false;
if(preg_match('/^[a-f0-9]{64}$/',$token)){try{$s=auth_db()->prepare('SELECT id FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1');$s->execute([hash('sha256',$token)]);$valid=(bool)$s->fetch();}catch(Throwable $e){$error='Password reset is not configured. Import auth_setup.sql first.';}}if(!$valid&&!$error)$error='This reset link is invalid, expired, or already used. Request a new one.';
if($_SERVER['REQUEST_METHOD']==='POST'&&$valid){$pass=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';if(strlen($pass)<10||!preg_match('/[A-Za-z]/',$pass)||!preg_match('/[0-9]/',$pass))$error='Use at least 10 characters, including at least one letter and one number.';elseif($pass!==$confirm)$error='The passwords do not match.';else{try{$db=auth_db();$db->beginTransaction();$s=$db->prepare('SELECT id,user_id FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() FOR UPDATE');$s->execute([hash('sha256',$token)]);$r=$s->fetch();if(!$r){$db->rollBack();$valid=false;$error='This reset link is no longer valid. Request a new one.';}else{$db->prepare('UPDATE auth_users SET password_hash=? WHERE id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),$r['user_id']]);$db->prepare('UPDATE password_resets SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$r['user_id']]);$db->commit();$success=true;}}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();$error='Unable to reset your password. Please try again.';}}}
auth_page_start('Choose a new password','Create a new password for your LabAsset account.');if($success){echo '<div class="auth-alert success">Your password has been updated. You can now sign in.</div><a class="auth-submit auth-link-button" href="login.php">Go to sign in →</a>';}else{if($error)echo '<div class="auth-alert error">'.h($error).'</div>';if($valid):?><form method="post" class="auth-form"><input type="hidden" name="token" value="<?= h($token) ?>"><label for="password">New password</label><input id="password" name="password" type="password" minlength="10" autocomplete="new-password" required><label for="confirm_password">Confirm new password</label><input id="confirm_password" name="confirm_password" type="password" minlength="10" autocomplete="new-password" required><button class="auth-submit" type="submit">Update password <span>→</span></button></form><?php endif;?><p class="auth-switch"><a href="forgot_password.php">Request another reset link</a></p><?php } auth_page_end(); ?>